parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "onderwerp": {
      "type": "string",
      "enum": ["warmtepomp", "ventilatie", "sanitair", "renovatie", "herstelling"]
    },
    "dringend": {
      "type": "boolean",
      "description": "true als iets kapot is of de klant zonder verwarming of water zit, anders false"
    },
    "samenvatting": {
      "type": "string",
      "description": "Hoogstens 15 woorden, in het Nederlands. Enkel wat de klant zelf zegt, geen vermoedens of oorzaken."
    }
  },
  "required": ["onderwerp", "dringend", "samenvatting"]
}

